import sys

data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
s = data[2]
dp = [1] * n
for i in range(n):
    for j in range(i):
        if abs(ord(s[i]) - ord(s[j])) <= k:
            dp[i] = max(dp[i], dp[j] + 1)
print(max(dp))

